// build-code-claude-005-replay: A Claude writer runs a granted selection and the engine reruns the set to convergence
func TestBuildCodeClaude005Replay(t *testing.T) {
	s := scenarios.New(t, "build-code-claude-005-replay")
	s.Given(`the "build-code-claude-replay" project tree`)
	s.And(`the System Architect answers "1" to every question`)
	s.When(`the System Architect runs "build code --fix"`)
	s.Then(`the command exits with code 0`)
	s.And(`the engine dispatched 1 fix AI turn to "claude"`)
	s.And(`the engine dispatched 1 apply AI turn to "claude"`)
	s.And(`the engine spawned exactly 3 test runners`)
	s.And(`the file "services/calc/calc.go" is modified`)
	s.And(`the file "tests/suite/calc_test.go" is unchanged`)
	s.And(`stdout matches BUILD CODE COMPLETE`)
	s.And(`every file matching "tmp/*/*apply*user.txt" matches go test -count=1 ./tests/suite/\.\.\. -run`)
	s.And(`the file "tmp/true-bdd.log.json" matches Bash`)
	s.And(`the shell command "go test -json -count=1 ./tests/suite/..." run in "." exits with code 0`)
	s.Done()
}

